customCss:
/* ==========================================================================
   AetherPOS Pro — High-Performance Dual-Pane Register & Themes
   ========================================================================== */

.wb-addon-pos-register {
  --pos-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --pos-mono: "Courier New", Courier, monospace;
  font-family: var(--pos-font);
  width: 100%;
  box-sizing: border-box;
  user-select: none;
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 40px rgba(0,0,0,0.3);
  transition: background-color 0.3s ease, color 0.3s ease;
}

.wb-addon-pos-register *,
.wb-addon-pos-register *::before,
.wb-addon-pos-register *::after {
  box-sizing: border-box;
}

/* ── 1. THEME PRESETS ── */
/* Theme 1: Midnight Cyber (Default Dark) */
.wb-addon-pos-register[data-pos-theme="midnight"],
.wb-addon-pos-register {
  --pos-bg: #0b0f19;
  --pos-card-bg: #131b2e;
  --pos-header-bg: #0f172a;
  --pos-border: rgba(255, 255, 255, 0.08);
  --pos-text: #f8fafc;
  --pos-text-dim: #94a3b8;
  --pos-accent: #10b981;
  --pos-accent-soft: rgba(16, 185, 129, 0.15);
  --pos-danger: #ef4444;
  --pos-warning: #f59e0b;
}

/* Theme 2: Clean Modern Light */
.wb-addon-pos-register[data-pos-theme="modern-light"] {
  --pos-bg: #f1f5f9;
  --pos-card-bg: #ffffff;
  --pos-header-bg: #ffffff;
  --pos-border: #e2e8f0;
  --pos-text: #0f172a;
  --pos-text-dim: #64748b;
  --pos-accent: #2563eb;
  --pos-accent-soft: rgba(37, 99, 235, 0.12);
  --pos-danger: #dc2626;
  --pos-warning: #d97706;
}

/* Theme 3: Warm Artisan Café */
.wb-addon-pos-register[data-pos-theme="artisan-cafe"] {
  --pos-bg: #1c1917;
  --pos-card-bg: #292524;
  --pos-header-bg: #24201e;
  --pos-border: rgba(245, 158, 11, 0.2);
  --pos-text: #fef3c7;
  --pos-text-dim: #d6d3d1;
  --pos-accent: #f59e0b;
  --pos-accent-soft: rgba(245, 158, 11, 0.16);
  --pos-danger: #f87171;
  --pos-warning: #fbbf24;
}

/* Theme 4: Classic Retail Terminal */
.wb-addon-pos-register[data-pos-theme="classic-retail"] {
  --pos-bg: #111827;
  --pos-card-bg: #1f2937;
  --pos-header-bg: #172033;
  --pos-border: rgba(5, 150, 105, 0.3);
  --pos-text: #ffffff;
  --pos-text-dim: #9ca3af;
  --pos-accent: #059669;
  --pos-accent-soft: rgba(5, 150, 105, 0.18);
  --pos-danger: #ef4444;
  --pos-warning: #f59e0b;
}

/* Applied Base Container */
.wb-addon-pos-register {
  background: var(--pos-bg);
  color: var(--pos-text);
}

/* ── 2. TOPBAR HEADER ── */
.pos-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  background: var(--pos-header-bg);
  border-bottom: 1px solid var(--pos-border);
  gap: 16px;
  flex-wrap: wrap;
}

.pos-topbar-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pos-brand-icon {
  font-size: 1.8rem;
  line-height: 1;
}

.pos-brand-title {
  font-size: 1.25rem;
  font-weight: 800;
  margin: 0;
  color: var(--pos-text);
  letter-spacing: -0.02em;
}

.pos-brand-subtitle {
  font-size: 0.75rem;
  color: var(--pos-text-dim);
  margin-top: 2px;
}

.pos-cashier-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--pos-accent-soft);
  color: var(--pos-accent);
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.7rem;
}

.pos-topbar-center {
  text-align: center;
}

.pos-clock {
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--pos-accent);
  font-variant-numeric: tabular-nums;
}

.pos-date {
  font-size: 0.72rem;
  color: var(--pos-text-dim);
}

.pos-topbar-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Quick Theme Toggle Buttons */
.pos-theme-picker {
  display: flex;
  align-items: center;
  gap: 4px;
  background: rgba(0, 0, 0, 0.2);
  padding: 3px;
  border-radius: 8px;
  border: 1px solid var(--pos-border);
}

.pos-theme-btn {
  background: transparent;
  border: none;
  font-size: 0.95rem;
  padding: 4px 6px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  line-height: 1;
}

.pos-theme-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  transform: scale(1.1);
}

.pos-btn-tool {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--pos-card-bg);
  color: var(--pos-text);
  border: 1px solid var(--pos-border);
  padding: 7px 12px;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.pos-btn-tool:hover {
  border-color: var(--pos-accent);
  color: var(--pos-accent);
  transform: translateY(-1px);
}

.pos-parked-count {
  background: var(--pos-warning);
  color: #000;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 800;
}

/* ── 3. MAIN DUAL-PANE LAYOUT ── */
.pos-main-container {
  display: grid;
  grid-template-columns: 1fr 380px;
  min-height: 640px;
  background: var(--pos-bg);
}

@media (max-width: 900px) {
  .pos-main-container {
    grid-template-columns: 1fr;
  }
}

/* ── LEFT: CATALOG & PRODUCTS ── */
.pos-catalog-panel {
  padding: 18px 20px;
  border-right: 1px solid var(--pos-border);
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-y: auto;
  max-height: 80vh;
}

/* Search Row */
.pos-search-row {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
}

.pos-search-box {
  flex: 1;
  min-width: 200px;
  position: relative;
  display: flex;
  align-items: center;
}

.pos-search-icon {
  position: absolute;
  left: 12px;
  font-size: 0.85rem;
  color: var(--pos-text-dim);
  pointer-events: none;
}

.pos-search-input {
  width: 100%;
  padding: 10px 34px 10px 36px;
  background: var(--pos-card-bg);
  border: 1px solid var(--pos-border);
  border-radius: 10px;
  color: var(--pos-text);
  font-size: 0.88rem;
  outline: none;
  transition: all 0.2s ease;
}

.pos-search-input:focus {
  border-color: var(--pos-accent);
  box-shadow: 0 0 0 3px var(--pos-accent-soft);
}

.pos-search-clear {
  position: absolute;
  right: 10px;
  background: transparent;
  border: none;
  color: var(--pos-text-dim);
  cursor: pointer;
  font-size: 0.8rem;
}

.pos-barcode-box {
  width: 220px;
  position: relative;
  display: flex;
  align-items: center;
}

.pos-barcode-icon {
  position: absolute;
  left: 10px;
  font-size: 0.8rem;
  color: var(--pos-accent);
  font-weight: 800;
  pointer-events: none;
}

.pos-barcode-input {
  width: 100%;
  padding: 10px 10px 10px 34px;
  background: var(--pos-card-bg);
  border: 1px dashed var(--pos-accent);
  border-radius: 10px;
  color: var(--pos-text);
  font-size: 0.82rem;
  outline: none;
  transition: all 0.2s ease;
}

.pos-barcode-input:focus {
  border-style: solid;
  box-shadow: 0 0 0 3px var(--pos-accent-soft);
}

/* Category Filter Tabs */
.pos-category-nav {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
}

.pos-category-pill {
  padding: 7px 14px;
  background: var(--pos-card-bg);
  border: 1px solid var(--pos-border);
  border-radius: 999px;
  color: var(--pos-text-dim);
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.pos-category-pill:hover,
.pos-category-pill.active {
  background: var(--pos-accent);
  color: #ffffff;
  border-color: var(--pos-accent);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px var(--pos-accent-soft);
}

/* Products Grid */
.pos-products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(145px, 1fr));
  gap: 12px;
}

.pos-product-card {
  background: var(--pos-card-bg);
  border: 1px solid var(--pos-border);
  border-radius: 12px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  overflow: hidden;
}

.pos-product-card:hover {
  transform: translateY(-3px);
  border-color: var(--pos-accent);
  box-shadow: 0 8px 24px -6px var(--pos-accent-soft);
}

.pos-product-card:active {
  transform: scale(0.97);
}

.pos-product-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 8px;
}

.pos-product-icon {
  font-size: 2rem;
  line-height: 1;
}

.pos-product-img {
  width: 48px;
  height: 48px;
  object-fit: cover;
  border-radius: 8px;
}

.pos-product-stock {
  font-size: 0.65rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--pos-text-dim);
}

.pos-product-name {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--pos-text);
  line-height: 1.25;
  margin-bottom: 6px;
}

.pos-product-sku {
  font-size: 0.68rem;
  color: var(--pos-text-dim);
  font-family: var(--pos-mono);
  margin-bottom: 10px;
}

.pos-product-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px dashed var(--pos-border);
}

.pos-product-price {
  font-size: 0.98rem;
  font-weight: 800;
  color: var(--pos-accent);
}

.pos-product-add-btn {
  background: var(--pos-accent-soft);
  color: var(--pos-accent);
  border: 1px solid transparent;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  font-weight: 800;
  transition: all 0.15s ease;
}

.pos-product-card:hover .pos-product-add-btn {
  background: var(--pos-accent);
  color: #fff;
}

/* ── RIGHT: LIVE ORDER TICKET ── */
.pos-ticket-panel {
  display: flex;
  flex-direction: column;
  background: var(--pos-card-bg);
  border-left: 1px solid var(--pos-border);
}

.pos-ticket-header {
  padding: 16px 18px;
  border-bottom: 1px solid var(--pos-border);
}

.pos-order-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.pos-order-num {
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--pos-text);
  font-family: var(--pos-mono);
}

.pos-ticket-badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--pos-accent-soft);
  color: var(--pos-accent);
}

.pos-order-types {
  display: flex;
  gap: 6px;
}

.pos-type-pill {
  flex: 1;
  padding: 6px 4px;
  font-size: 0.74rem;
  font-weight: 600;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--pos-border);
  color: var(--pos-text-dim);
  cursor: pointer;
  text-align: center;
  transition: all 0.2s ease;
}

.pos-type-pill.active {
  background: var(--pos-accent);
  color: #fff;
  border-color: var(--pos-accent);
  box-shadow: 0 2px 8px var(--pos-accent-soft);
}

/* Items List */
.pos-ticket-items {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 220px;
  max-height: 380px;
}

.pos-ticket-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 40px 16px;
  color: var(--pos-text-dim);
}

.pos-empty-icon {
  font-size: 2.5rem;
  margin-bottom: 8px;
  opacity: 0.6;
}

.pos-empty-title {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--pos-text);
  margin-bottom: 4px;
}

.pos-empty-sub {
  font-size: 0.75rem;
  line-height: 1.4;
  max-width: 220px;
}

/* Single Ticket Item Row */
.pos-ticket-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--pos-border);
  border-radius: 10px;
  transition: background 0.15s ease;
}

.pos-ticket-row:hover {
  background: rgba(255, 255, 255, 0.06);
}

.pos-item-info {
  min-width: 0;
}

.pos-item-title {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--pos-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pos-item-unit-price {
  font-size: 0.72rem;
  color: var(--pos-text-dim);
}

.pos-qty-stepper {
  display: inline-flex;
  align-items: center;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--pos-border);
  border-radius: 6px;
  overflow: hidden;
}

.pos-step-btn {
  background: transparent;
  border: none;
  color: var(--pos-text);
  width: 24px;
  height: 24px;
  font-size: 0.85rem;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pos-step-btn:hover {
  background: var(--pos-accent-soft);
  color: var(--pos-accent);
}

.pos-step-val {
  font-size: 0.78rem;
  font-weight: 700;
  width: 24px;
  text-align: center;
  color: var(--pos-text);
}

.pos-item-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pos-item-total {
  font-size: 0.88rem;
  font-weight: 800;
  color: var(--pos-text);
  font-family: var(--pos-mono);
  min-width: 58px;
  text-align: right;
}

.pos-item-remove {
  background: transparent;
  border: none;
  color: var(--pos-text-dim);
  cursor: pointer;
  font-size: 0.78rem;
  padding: 2px 4px;
  border-radius: 4px;
  transition: all 0.15s ease;
}

.pos-item-remove:hover {
  color: var(--pos-danger);
  background: rgba(239, 68, 68, 0.15);
}

/* Ticket Calculations Summary */
.pos-ticket-summary {
  padding: 16px 18px;
  border-top: 1px solid var(--pos-border);
  background: rgba(0, 0, 0, 0.15);
}

.pos-discount-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.pos-summary-label {
  font-size: 0.76rem;
  color: var(--pos-text-dim);
  font-weight: 600;
}

.pos-discount-select {
  padding: 5px 10px;
  background: var(--pos-card-bg);
  border: 1px solid var(--pos-border);
  border-radius: 6px;
  color: var(--pos-text);
  font-size: 0.76rem;
  outline: none;
}

.pos-summary-line {
  display: flex;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--pos-text-dim);
  margin-bottom: 6px;
  font-family: var(--pos-mono);
}

.pos-discount-line {
  color: var(--pos-accent);
}

.pos-total-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 10px;
  margin-top: 8px;
  border-top: 1px solid var(--pos-border);
}

.pos-total-label {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--pos-text);
  letter-spacing: 0.04em;
}

.pos-total-amount {
  font-size: 1.65rem;
  font-weight: 900;
  color: var(--pos-accent);
  font-family: var(--pos-mono);
  letter-spacing: -0.02em;
}

/* Action Buttons */
.pos-ticket-actions {
  display: grid;
  grid-template-columns: 1fr 1fr 2.2fr;
  gap: 8px;
  margin-top: 14px;
}

.pos-btn-action {
  padding: 12px 10px;
  border-radius: 10px;
  font-size: 0.82rem;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

.pos-btn-clear {
  background: rgba(239, 68, 68, 0.12);
  color: var(--pos-danger);
  border-color: rgba(239, 68, 68, 0.25);
}

.pos-btn-clear:hover {
  background: var(--pos-danger);
  color: #fff;
}

.pos-btn-park {
  background: rgba(245, 158, 11, 0.12);
  color: var(--pos-warning);
  border-color: rgba(245, 158, 11, 0.25);
}

.pos-btn-park:hover {
  background: var(--pos-warning);
  color: #000;
}

.pos-btn-checkout {
  background: var(--pos-accent);
  color: #ffffff;
  box-shadow: 0 4px 14px var(--pos-accent-soft);
}

.pos-btn-checkout:hover:not(:disabled) {
  filter: brightness(1.1);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--pos-accent-soft);
}

.pos-btn-checkout:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  filter: grayscale(1);
}

/* ── 4. MODALS & POPUPS ── */
.pos-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(6px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.pos-modal-box {
  background: var(--pos-card-bg);
  border: 1px solid var(--pos-border);
  border-radius: 16px;
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  color: var(--pos-text);
}

.pos-modal-header {
  padding: 16px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--pos-border);
}

.pos-modal-title {
  font-size: 1.1rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pos-modal-close {
  background: transparent;
  border: none;
  font-size: 1rem;
  color: var(--pos-text-dim);
  cursor: pointer;
  padding: 4px;
}

.pos-modal-close:hover {
  color: var(--pos-text);
}

.pos-modal-body {
  padding: 20px;
  overflow-y: auto;
  flex: 1;
}

.pos-checkout-banner {
  text-align: center;
  padding: 16px;
  background: var(--pos-accent-soft);
  border: 1px solid var(--pos-accent);
  border-radius: 12px;
  margin-bottom: 16px;
}

.pos-banner-label {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--pos-accent);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pos-banner-total {
  font-size: 2.2rem;
  font-weight: 900;
  color: var(--pos-text);
  font-family: var(--pos-mono);
  margin-top: 4px;
}

/* Pay Tabs */
.pos-pay-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.pos-pay-tab {
  flex: 1;
  padding: 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--pos-border);
  border-radius: 8px;
  color: var(--pos-text-dim);
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.2s ease;
}

.pos-pay-tab.active {
  background: var(--pos-accent);
  color: #fff;
  border-color: var(--pos-accent);
}

.pos-cash-input-wrap {
  margin-bottom: 12px;
}

.pos-input-label {
  display: block;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--pos-text-dim);
  margin-bottom: 6px;
}

.pos-cash-input,
.pos-text-input {
  width: 100%;
  padding: 12px 14px;
  font-size: 1.3rem;
  font-weight: 800;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--pos-border);
  border-radius: 10px;
  color: var(--pos-text);
  font-family: var(--pos-mono);
  outline: none;
}

.pos-cash-input:focus,
.pos-text-input:focus {
  border-color: var(--pos-accent);
  box-shadow: 0 0 0 3px var(--pos-accent-soft);
}

/* Quick Bills */
.pos-quick-bills {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  margin-bottom: 16px;
}

.pos-bill-btn {
  padding: 8px 4px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--pos-border);
  border-radius: 8px;
  color: var(--pos-text);
  font-size: 0.78rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
}

.pos-bill-btn:hover {
  background: var(--pos-accent-soft);
  color: var(--pos-accent);
  border-color: var(--pos-accent);
}

/* Change Banner */
.pos-change-banner {
  padding: 14px;
  border-radius: 10px;
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid var(--pos-accent);
  text-align: center;
  transition: all 0.2s ease;
}

.pos-change-banner.insufficient {
  background: rgba(245, 158, 11, 0.15);
  border-color: var(--pos-warning);
}

.pos-change-label {
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--pos-accent);
}

.pos-change-banner.insufficient .pos-change-label {
  color: var(--pos-warning);
}

.pos-change-val {
  font-size: 1.6rem;
  font-weight: 900;
  font-family: var(--pos-mono);
  margin-top: 2px;
}

/* QR Box */
.pos-qr-box {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--pos-border);
  border-radius: 12px;
}

.pos-qr-img {
  width: 100px;
  height: 100px;
  object-fit: contain;
  background: #ffffff;
  padding: 6px;
  border-radius: 8px;
}

.pos-qr-merchant {
  font-size: 1rem;
  font-weight: 800;
  color: var(--pos-text);
  margin-bottom: 4px;
}

.pos-qr-num {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--pos-accent);
  font-family: var(--pos-mono);
  margin-bottom: 6px;
}

.pos-qr-sub {
  font-size: 0.74rem;
  color: var(--pos-text-dim);
}

.pos-card-note {
  font-size: 0.76rem;
  color: var(--pos-text-dim);
  margin-top: 8px;
  line-height: 1.4;
}

/* Modal Footer */
.pos-modal-footer {
  padding: 14px 20px;
  border-top: 1px solid var(--pos-border);
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  background: rgba(0, 0, 0, 0.15);
}

.pos-btn-dialog {
  padding: 10px 18px;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

.pos-btn-cancel {
  background: rgba(255, 255, 255, 0.08);
  color: var(--pos-text);
}

.pos-btn-submit {
  background: var(--pos-accent);
  color: #fff;
}

.pos-btn-submit:hover:not(:disabled) {
  filter: brightness(1.1);
}

.pos-btn-submit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ── 5. THERMAL RECEIPT (80mm PAPER SIMULATION) ── */
.pos-receipt-box {
  max-width: 420px;
}

.pos-thermal-receipt {
  background: #ffffff;
  color: #000000;
  font-family: var(--pos-mono);
  font-size: 12px;
  line-height: 1.35;
  padding: 24px 20px;
  border-radius: 4px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
  margin: 0 auto;
}

.pos-rcpt-header {
  text-align: center;
  margin-bottom: 8px;
}

.pos-rcpt-store {
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.pos-rcpt-sub,
.pos-rcpt-addr,
.pos-rcpt-tin {
  font-size: 11px;
  color: #333;
}

.pos-rcpt-divider {
  text-align: center;
  margin: 6px 0;
  letter-spacing: -1px;
  color: #666;
  font-size: 10px;
}

.pos-rcpt-meta {
  font-size: 11px;
  margin-bottom: 6px;
}

.pos-rcpt-items {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pos-rcpt-item-row {
  display: flex;
  justify-content: space-between;
}

.pos-rcpt-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 2px;
}

.pos-rcpt-total {
  font-size: 14px;
  font-weight: 900;
  margin-top: 4px;
}

.pos-rcpt-change {
  font-size: 13px;
  font-weight: 900;
}

.pos-rcpt-footer {
  text-align: center;
  margin-top: 10px;
}

.pos-rcpt-thankyou {
  font-weight: 700;
  font-size: 11px;
  margin-bottom: 6px;
}

.pos-rcpt-barcode {
  letter-spacing: 2px;
  font-size: 14px;
  margin: 6px 0;
}

.pos-rcpt-sys {
  font-size: 9px;
  color: #777;
}

/* ── 6. PRINT CSS ENGINE (PRINTS ONLY RECEIPT ROLL) ── */
@media print {
  body * {
    visibility: hidden !important;
  }
  .pos-thermal-receipt,
  .pos-thermal-receipt * {
    visibility: visible !important;
  }
  .pos-thermal-receipt {
    position: fixed !important;
    left: 0 !important;
    top: 0 !important;
    width: 80mm !important;
    margin: 0 !important;
    padding: 10px !important;
    box-shadow: none !important;
    background: #ffffff !important;
    color: #000000 !important;
  }
  .no-print {
