  }
}

/* ── 7. SHIFT REPORT MODAL ── */
.pos-report-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 16px;
}

.pos-stat-card {
  padding: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--pos-border);
  border-radius: 10px;
  text-align: center;
}

.pos-stat-label {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--pos-text-dim);
  text-transform: uppercase;
}

.pos-stat-val {
  font-size: 1.15rem;
  font-weight: 900;
  color: var(--pos-accent);
  margin-top: 4px;
  font-family: var(--pos-mono);
}

.pos-report-history {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 220px;
  overflow-y: auto;
}

.pos-history-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--pos-border);
  border-radius: 8px;
  font-size: 0.8rem;
}

customJs:
function onMount(el, props) {
  var root = el.querySelector('.wb-addon-pos-register');
  if (!root) return;

  var $ = function(sel, ctx) { return (ctx || root).querySelector(sel); };
  var $$ = function(sel, ctx) { return Array.from((ctx || root).querySelectorAll(sel)); };
  var curr = props.currencySymbol || '₱';

  // --- 1. LOCAL STORAGE STATE ---
  var orderSeq = parseInt(localStorage.getItem('aether_pos_seq') || '1001', 10);
  var salesHistory = [];
  try { salesHistory = JSON.parse(localStorage.getItem('aether_pos_sales') || '[]'); } catch(e){}
  var parkedOrders = [];
  try { parkedOrders = JSON.parse(localStorage.getItem('aether_pos_parked') || '[]'); } catch(e){}

  // --- 2. ACTIVE REGISTER STATE ---
  var activeCart = [];
  var activeCategory = 'All';
  var activeSearch = '';
  var activeOrderType = 'Dine-in';
  var activeDiscountPct = 0;
  var currentPayMethod = 'cash';

  // Set order number display
  var updateOrderNumber = function() {
    var ordEl = $('#pos-order-num');
    if (ordEl) ordEl.textContent = '#ORD-' + orderSeq;
  };
  updateOrderNumber();

  // Update Parked Count Badge
  var updateParkedBadge = function() {
    var badge = $('.pos-parked-count');
    if (badge) badge.textContent = parkedOrders.length;
  };
  updateParkedBadge();

  // --- 3. THEME SWITCHER ---
  $$('.pos-theme-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var theme = btn.getAttribute('data-theme');
      if (theme) {
        root.setAttribute('data-pos-theme', theme);
      }
    });
  });

  // --- 4. LIVE CLOCK & DATE ---
  var clockEl = $('#pos-live-clock');
  var dateEl = $('#pos-live-date');
  var updateClock = function() {
    var now = new Date();
    if (clockEl) {
      clockEl.textContent = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }
    if (dateEl) {
      dateEl.textContent = now.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
    }
  };
  updateClock();
  var clockTimer = setInterval(updateClock, 1000);

  // --- 5. PRODUCTS & CATEGORIES ---
  var products = Array.isArray(props.products) && props.products.length ? props.products : [
    { id: 'p1', name: 'Espresso Romano', category: 'Coffee & Drinks', price: 120, sku: 'CF-001', icon: '☕', stock: 45 },
    { id: 'p2', name: 'Caramel Macchiato', category: 'Coffee & Drinks', price: 165, sku: 'CF-002', icon: '🥤', stock: 32 },
    { id: 'p3', name: 'Matcha Latte', category: 'Coffee & Drinks', price: 175, sku: 'CF-003', icon: '🍵', stock: 28 },
    { id: 'p4', name: 'Butter Croissant', category: 'Bakery & Pastry', price: 95, sku: 'BK-001', icon: '🥐', stock: 20 },
    { id: 'p5', name: 'Blueberry Cheesecake', category: 'Bakery & Pastry', price: 180, sku: 'BK-002', icon: '🍰', stock: 14 },
    { id: 'p6', name: 'Panini Sandwich', category: 'Meals', price: 240, sku: 'ML-001', icon: '🥪', stock: 18 },
    { id: 'p7', name: 'Caesar Salad Bowl', category: 'Meals', price: 210, sku: 'ML-002', icon: '🥗', stock: 15 },
    { id: 'p8', name: 'Coffee Tumbler', category: 'Merchandise', price: 550, sku: 'MC-001', icon: '🍶', stock: 8 }
  ];

  var catNav = $('#pos-category-nav');
  var prodGrid = $('#pos-products-grid');

  // Render Categories Nav
  var renderCategories = function() {
    if (!catNav) return;
    var rawCats = (props.categories || 'All, Coffee & Drinks, Bakery & Pastry, Meals, Merchandise').split(',');
    var catList = ['All'];
    rawCats.forEach(function(c) {
      var trimmed = c.trim();
      if (trimmed && trimmed.toLowerCase() !== 'all' && catList.indexOf(trimmed) === -1) {
        catList.push(trimmed);
      }
    });

    catNav.innerHTML = catList.map(function(cat) {
      return '<button type="button" class="pos-category-pill ' + (cat === activeCategory ? 'active' : '') + '" data-cat="' + cat + '">' + cat + '</button>';
    }).join('');

    $$('.pos-category-pill', catNav).forEach(function(pill) {
      pill.addEventListener('click', function() {
        $$('.pos-category-pill', catNav).forEach(function(p){ p.classList.remove('active'); });
        pill.classList.add('active');
        activeCategory = pill.getAttribute('data-cat') || 'All';
        renderProducts();
      });
    });
  };
  renderCategories();

  // Render Products Grid
  var renderProducts = function() {
    if (!prodGrid) return;
    var searchLower = activeSearch.toLowerCase().trim();
    var filtered = products.filter(function(p) {
      var catMatch = (activeCategory === 'All') || (p.category === activeCategory);
      var searchMatch = !searchLower || (p.name && p.name.toLowerCase().indexOf(searchLower) !== -1) || (p.sku && p.sku.toLowerCase().indexOf(searchLower) !== -1);
      return catMatch && searchMatch;
    });

    if (!filtered.length) {
      prodGrid.innerHTML = '<div style="grid-column: 1/-1; padding: 40px 10px; text-align: center; color: var(--pos-text-dim);"><div style="font-size:2rem; margin-bottom:6px;">🔍</div><div>No products match your search or category filter.</div></div>';
      return;
    }

    prodGrid.innerHTML = filtered.map(function(p, pIdx) {
      var visual = p.imageUrl
        ? '<img src="' + p.imageUrl + '" alt="' + p.name + '" class="pos-product-img">'
        : '<span class="pos-product-icon">' + (p.icon || '📦') + '</span>';
      var stockLabel = p.stock != null ? (p.stock > 0 ? p.stock + ' in stock' : 'Out of stock') : 'Available';

      return '<div class="pos-product-card" data-idx="' + pIdx + '" data-id="' + (p.id || p.sku || p.name) + '">' +
        '<div class="pos-product-top">' + visual + '<span class="pos-product-stock">' + stockLabel + '</span></div>' +
        '<div class="pos-product-name">' + (p.name || 'Product') + '</div>' +
        '<div class="pos-product-sku">' + (p.sku || '') + '</div>' +
        '<div class="pos-product-bottom">' +
          '<div class="pos-product-price">' + curr + Number(p.price || 0).toFixed(2) + '</div>' +
          '<div class="pos-product-add-btn">+</div>' +
        '</div>' +
      '</div>';
    }).join('');

    $$('.pos-product-card', prodGrid).forEach(function(card) {
      card.addEventListener('click', function() {
        var pId = card.getAttribute('data-id');
        var item = products.find(function(p) { return (p.id || p.sku || p.name) === pId; });
        if (item) {
          addToCart(item);
        }
      });
    });
  };
  renderProducts();

  // Search Input Filter
  var searchInput = $('#pos-search-input');
  var clearSearchBtn = $('#pos-search-clear');
  if (searchInput) {
    searchInput.addEventListener('input', function(e) {
      activeSearch = e.target.value;
      if (clearSearchBtn) clearSearchBtn.style.display = activeSearch ? 'block' : 'none';
      renderProducts();
    });
  }
  if (clearSearchBtn) {
    clearSearchBtn.addEventListener('click', function() {
      if (searchInput) searchInput.value = '';
      activeSearch = '';
      clearSearchBtn.style.display = 'none';
      renderProducts();
    });
  }

  // Fast Barcode Scanner input
  var barcodeInput = $('#pos-barcode-input');
  if (barcodeInput) {
    barcodeInput.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') {
        var code = barcodeInput.value.trim().toLowerCase();
        if (code) {
          var found = products.find(function(p) { return p.sku && p.sku.toLowerCase() === code; });
          if (found) {
            addToCart(found);
            barcodeInput.value = '';
            barcodeInput.style.borderColor = 'var(--pos-accent)';
            setTimeout(function(){ barcodeInput.style.borderColor = ''; }, 600);
          } else {
            barcodeInput.style.borderColor = 'var(--pos-danger)';
            setTimeout(function(){ barcodeInput.style.borderColor = ''; }, 800);
          }
        }
      }
    });
  }

  // --- 6. CART & TICKET LOGIC ---
  var addToCart = function(product) {
    var pId = product.id || product.sku || product.name;
    var existing = activeCart.find(function(item) { return item.id === pId; });
    if (existing) {
      existing.qty += 1;
    } else {
      activeCart.push({
        id: pId,
        name: product.name,
        price: Number(product.price || 0),
        qty: 1,
        sku: product.sku || '',
        icon: product.icon || '📦'
      });
    }
    renderTicket();
  };

  var updateCartQty = function(id, delta) {
    var idx = activeCart.findIndex(function(item) { return item.id === id; });
    if (idx !== -1) {
      activeCart[idx].qty += delta;
      if (activeCart[idx].qty <= 0) {
        activeCart.splice(idx, 1);
      }
    }
    renderTicket();
  };

  var removeCartItem = function(id) {
    activeCart = activeCart.filter(function(item) { return item.id !== id; });
    renderTicket();
  };

  var ticketItemsEl = $('#pos-ticket-items');
  var countBadge = $('#pos-ticket-items-count');
  var subtotalValEl = $('#pos-subtotal-val');
  var discValEl = $('#pos-discount-val');
  var discLineEl = $('#pos-discount-line');
  var discPctEl = $('#pos-discount-pct');
  var taxValEl = $('#pos-tax-val');
  var totalValEl = $('#pos-total-val');
  var checkoutBtn = $('#pos-btn-checkout');

  var getOrderCalculations = function() {
    var subtotal = activeCart.reduce(function(acc, item) { return acc + (item.price * item.qty); }, 0);
    var discount = subtotal * (activeDiscountPct / 100);
    var taxableAmount = Math.max(0, subtotal - discount);
    var taxRate = props.enableTax ? Number(props.taxRate || 12) : 0;
    var tax = taxableAmount * (taxRate / 100);
    var total = taxableAmount + tax;
    var totalItemsCount = activeCart.reduce(function(acc, item) { return acc + item.qty; }, 0);

    return {
      subtotal: subtotal,
      discount: discount,
      tax: tax,
      total: total,
      totalItemsCount: totalItemsCount
    };
  };

  var renderTicket = function() {
    if (!ticketItemsEl) return;

    if (!activeCart.length) {
      ticketItemsEl.innerHTML = '<div class="pos-ticket-empty">' +
        '<div class="pos-empty-icon">🛒</div>' +
        '<div class="pos-empty-title">Ticket is Empty</div>' +
        '<div class="pos-empty-sub">Tap any item from the catalog or scan barcode to add to current order</div>' +
      '</div>';
      if (countBadge) countBadge.textContent = '0 Items';
      if (subtotalValEl) subtotalValEl.textContent = curr + '0.00';
      if (discLineEl) discLineEl.style.display = 'none';
      if (taxValEl) taxValEl.textContent = curr + '0.00';
      if (totalValEl) totalValEl.textContent = curr + '0.00';
      if (checkoutBtn) checkoutBtn.disabled = true;
      return;
    }

    ticketItemsEl.innerHTML = activeCart.map(function(item) {
      var itemTotal = (item.price * item.qty).toFixed(2);
      return '<div class="pos-ticket-row" data-id="' + item.id + '">' +
        '<div class="pos-item-info">' +
          '<div class="pos-item-title">' + item.name + '</div>' +
          '<div class="pos-item-unit-price">' + curr + item.price.toFixed(2) + ' each</div>' +
        '</div>' +
        '<div class="pos-qty-stepper">' +
          '<button type="button" class="pos-step-btn pos-btn-dec" data-id="' + item.id + '">-</button>' +
          '<span class="pos-step-val">' + item.qty + '</span>' +
          '<button type="button" class="pos-step-btn pos-btn-inc" data-id="' + item.id + '">+</button>' +
        '</div>' +
        '<div class="pos-item-actions">' +
          '<div class="pos-item-total">' + curr + itemTotal + '</div>' +
          '<button type="button" class="pos-item-remove" data-id="' + item.id + '" title="Remove item">✕</button>' +
        '</div>' +
      '</div>';
    }).join('');

    // Wire Quantity Steppers & Remove
    $$('.pos-btn-dec', ticketItemsEl).forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        updateCartQty(btn.getAttribute('data-id'), -1);
      });
    });
    $$('.pos-btn-inc', ticketItemsEl).forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        updateCartQty(btn.getAttribute('data-id'), 1);
      });
    });
    $$('.pos-item-remove', ticketItemsEl).forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        removeCartItem(btn.getAttribute('data-id'));
      });
    });

    // Update Totals
    var calc = getOrderCalculations();
    if (countBadge) countBadge.textContent = calc.totalItemsCount + ' Item' + (calc.totalItemsCount > 1 ? 's' : '');
    if (subtotalValEl) subtotalValEl.textContent = curr + calc.subtotal.toFixed(2);

    if (activeDiscountPct > 0) {
      if (discLineEl) discLineEl.style.display = 'flex';
      if (discPctEl) discPctEl.textContent = activeDiscountPct;
      if (discValEl) discValEl.textContent = '-' + curr + calc.discount.toFixed(2);
    } else {
      if (discLineEl) discLineEl.style.display = 'none';
    }

    if (taxValEl) taxValEl.textContent = curr + calc.tax.toFixed(2);
    if (totalValEl) totalValEl.textContent = curr + calc.total.toFixed(2);
    if (checkoutBtn) checkoutBtn.disabled = false;
  };

  // Order Type Pills
  $$('.pos-type-pill').forEach(function(pill) {
    pill.addEventListener('click', function() {
      $$('.pos-type-pill').forEach(function(p){ p.classList.remove('active'); });
      pill.classList.add('active');
      activeOrderType = pill.getAttribute('data-type') || 'Dine-in';
    });
  });

  // Discount Select Dropdown
  var discountSelect = $('#pos-discount-select');
  if (discountSelect) {
    discountSelect.addEventListener('change', function(e) {
      activeDiscountPct = parseFloat(e.target.value) || 0;
      renderTicket();
    });
  }

  // Clear Ticket Button
  var clearBtn = $('#pos-btn-clear');
  if (clearBtn) {
    clearBtn.addEventListener('click', function() {
      if (!activeCart.length) return;
      if (confirm('Clear current ticket? Items will be emptied.')) {
        activeCart = [];
        renderTicket();
      }
    });
  }

  // Hold / Park Order
  var parkBtn = $('#pos-btn-park');
  if (parkBtn) {
    parkBtn.addEventListener('click', function() {
      if (!activeCart.length) {
        alert('Active ticket is empty. Nothing to park.');
        return;
      }
      parkedOrders.push({
        orderNum: '#ORD-' + orderSeq,
        timestamp: new Date().toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }),
        orderType: activeOrderType,
        items: activeCart,
        discountPct: activeDiscountPct
      });
      localStorage.setItem('aether_pos_parked', JSON.stringify(parkedOrders));
      updateParkedBadge();

      // Increment sequence for next customer
      orderSeq++;
      localStorage.setItem('aether_pos_seq', String(orderSeq));
      updateOrderNumber();

      activeCart = [];
      activeDiscountPct = 0;
      if (discountSelect) discountSelect.value = '0';
      renderTicket();
      alert('Order parked successfully. You can now ring up the next customer.');
    });
  }

  // Recall Parked Orders Button
  var recallBtn = $('#pos-btn-recall-parked');
  if (recallBtn) {
    recallBtn.addEventListener('click', function() {
      if (!parkedOrders.length) {
        alert('No parked orders on hold.');
        return;
      }
      var listStr = parkedOrders.map(function(po, idx) {
        var count = po.items.reduce(function(acc, i){ return acc + i.qty; }, 0);
        return (idx + 1) + '. ' + po.orderNum + ' (' + po.orderType + ' - ' + count + ' items at ' + po.timestamp + ')';
      }).join('\n');

      var choice = prompt('Select parked order to restore (enter number 1-' + parkedOrders.length + '):\n\n' + listStr);
      if (choice) {
        var num = parseInt(choice, 10);
        if (num >= 1 && num <= parkedOrders.length) {
          var restored = parkedOrders.splice(num - 1, 1)[0];
          localStorage.setItem('aether_pos_parked', JSON.stringify(parkedOrders));
          updateParkedBadge();
          activeCart = restored.items;
          activeOrderType = restored.orderType;
          activeDiscountPct = restored.discountPct || 0;
          if (discountSelect) discountSelect.value = String(activeDiscountPct);
          $$('.pos-type-pill').forEach(function(p) {
            p.classList.toggle('active', p.getAttribute('data-type') === activeOrderType);
          });
          renderTicket();
        }
      }
    });
  }

  // --- 7. CHECKOUT & TENDER PAYMENT MODAL ---
  var modalCheckout = $('#pos-modal-checkout');
  var closeCheckout = $('#pos-close-checkout');
  var cancelCheckout = $('#pos-cancel-checkout');
  var checkoutDueEl = $('#pos-checkout-due');
  var cashInput = $('#pos-cash-tendered');
  var changeValEl = $('#pos-change-val');
  var changeBanner = $('#pos-change-banner');
  var completeSaleBtn = $('#pos-btn-complete-sale');

  var currentTotalDue = 0;

  var openCheckoutModal = function() {
    var calc = getOrderCalculations();
    currentTotalDue = calc.total;
    if (checkoutDueEl) checkoutDueEl.textContent = curr + currentTotalDue.toFixed(2);
    if (cashInput) { cashInput.value = ''; cashInput.placeholder = currentTotalDue.toFixed(2); }
    if (changeValEl) changeValEl.textContent = curr + '0.00';
    if (changeBanner) changeBanner.className = 'pos-change-banner';
    if (completeSaleBtn) completeSaleBtn.disabled = true;

    // Default to Cash tab
    setPayTab('cash');
    if (modalCheckout) modalCheckout.style.display = 'flex';
  };

  var closeCheckoutModal = function() {
    if (modalCheckout) modalCheckout.style.display = 'none';
  };

  if (checkoutBtn) checkoutBtn.addEventListener('click', openCheckoutModal);
  if (closeCheckout) closeCheckout.addEventListener('click', closeCheckoutModal);
  if (cancelCheckout) cancelCheckout.addEventListener('click', closeCheckoutModal);

  // Payment Tabs Switcher
  var setPayTab = function(tabName) {
    currentPayMethod = tabName;
    $$('.pos-pay-tab').forEach(function(tab) {
      tab.classList.toggle('active', tab.getAttribute('data-tab') === tabName);
    });
    var paneCash = $('#pos-pane-cash');
    var paneQr = $('#pos-pane-qr');
    var paneCard = $('#pos-pane-card');

    if (paneCash) paneCash.style.display = tabName === 'cash' ? 'block' : 'none';
    if (paneQr) paneQr.style.display = tabName === 'qr' ? 'block' : 'none';
    if (paneCard) paneCard.style.display = tabName === 'card' ? 'block' : 'none';

    // Enable complete sale immediately for QR or Card
    if (tabName === 'qr' || tabName === 'card') {
      if (completeSaleBtn) completeSaleBtn.disabled = false;
    } else {
      evaluateCashTender();
    }
  };

  $$('.pos-pay-tab').forEach(function(tab) {
    tab.addEventListener('click', function() {
      setPayTab(tab.getAttribute('data-tab'));
    });
  });

  // Evaluate Cash Tender & Compute Change
  var evaluateCashTender = function() {
    if (currentPayMethod !== 'cash') return;
    var tendered = parseFloat(cashInput ? cashInput.value : 0) || 0;
    var change = tendered - currentTotalDue;

    if (tendered >= currentTotalDue) {
      if (changeBanner) changeBanner.className = 'pos-change-banner';
      if (changeValEl) changeValEl.textContent = curr + change.toFixed(2);
      if (completeSaleBtn) completeSaleBtn.disabled = false;
    } else {
      if (changeBanner) changeBanner.className = 'pos-change-banner insufficient';
      var needed = currentTotalDue - tendered;
      if (changeValEl) changeValEl.textContent = 'Due: ' + curr + needed.toFixed(2);
      if (completeSaleBtn) completeSaleBtn.disabled = true;
    }
  };

  if (cashInput) cashInput.addEventListener('input', evaluateCashTender);

  // Quick Cash Bills
  $$('.pos-bill-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var val = btn.getAttribute('data-val');
      if (val === 'exact') {
        if (cashInput) cashInput.value = currentTotalDue.toFixed(2);
      } else {
        var num = parseFloat(val) || 0;
        var cur = parseFloat(cashInput.value) || 0;
        if (cashInput) cashInput.value = (cur + num).toFixed(2);
      }
      evaluateCashTender();
    });
  });

  // --- 8. RECEIPT & SALE COMPLETION ---
  var modalReceipt = $('#pos-modal-receipt');
  var closeReceipt = $('#pos-close-receipt');
  var newOrderBtn = $('#pos-btn-new-order');
  var printReceiptBtn = $('#pos-btn-print-receipt');

  var completeSale = function() {
    var calc = getOrderCalculations();
    var tendered = currentPayMethod === 'cash' ? (parseFloat(cashInput ? cashInput.value : 0) || calc.total) : calc.total;
    var change = Math.max(0, tendered - calc.total);
    var now = new Date();

    var saleRecord = {
      orderNum: '#ORD-' + orderSeq,
      timestamp: now.toISOString(),
      displayDate: now.toLocaleDateString() + ' ' + now.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }),
      orderType: activeOrderType,
      items: activeCart,
      subtotal: calc.subtotal,
      discount: calc.discount,
      discountPct: activeDiscountPct,
      tax: calc.tax,
      total: calc.total,
      payMethod: currentPayMethod.toUpperCase(),
      tendered: tendered,
      change: change,
      cashier: props.cashierName || 'Admin'
    };

    // Save to sales history
    salesHistory.unshift(saleRecord);
    if (salesHistory.length > 500) salesHistory = salesHistory.slice(0, 500);
    localStorage.setItem('aether_pos_sales', JSON.stringify(salesHistory));

    // Populate Thermal Receipt DOM
    var rcptOrdNum = $('#pos-rcpt-ord-num');
    var rcptDate = $('#pos-rcpt-date');
    var rcptType = $('#pos-rcpt-type');
    var rcptItemsList = $('#pos-rcpt-items-list');
    var rcptSubtotal = $('#pos-rcpt-subtotal');
    var rcptDiscRow = $('#pos-rcpt-disc-row');
    var rcptDiscount = $('#pos-rcpt-discount');
    var rcptTax = $('#pos-rcpt-tax');
    var rcptTotal = $('#pos-rcpt-total');
    var rcptMethod = $('#pos-rcpt-method');
    var rcptTendered = $('#pos-rcpt-tendered');
    var rcptChange = $('#pos-rcpt-change');

    if (rcptOrdNum) rcptOrdNum.textContent = saleRecord.orderNum;
    if (rcptDate) rcptDate.textContent = saleRecord.displayDate;
    if (rcptType) rcptType.textContent = saleRecord.orderType;

    if (rcptItemsList) {
      rcptItemsList.innerHTML = saleRecord.items.map(function(item) {
        return '<div class="pos-rcpt-item-row">' +
          '<span>' + item.qty + 'x ' + item.name + '</span>' +
          '<span>' + curr + (item.price * item.qty).toFixed(2) + '</span>' +
        '</div>';
      }).join('');
    }

    if (rcptSubtotal) rcptSubtotal.textContent = curr + saleRecord.subtotal.toFixed(2);
    if (saleRecord.discount > 0) {
      if (rcptDiscRow) rcptDiscRow.style.display = 'flex';
      if (rcptDiscount) rcptDiscount.textContent = '-' + curr + saleRecord.discount.toFixed(2) + ' (' + saleRecord.discountPct + '%)';
    } else {
      if (rcptDiscRow) rcptDiscRow.style.display = 'none';
    }

    if (rcptTax) rcptTax.textContent = curr + saleRecord.tax.toFixed(2);
    if (rcptTotal) rcptTotal.textContent = curr + saleRecord.total.toFixed(2);
    if (rcptMethod) rcptMethod.textContent = saleRecord.payMethod;
    if (rcptTendered) rcptTendered.textContent = curr + saleRecord.tendered.toFixed(2);
    if (rcptChange) rcptChange.textContent = curr + saleRecord.change.toFixed(2);

    // Close checkout and show receipt
    closeCheckoutModal();
    if (modalReceipt) modalReceipt.style.display = 'flex';

    // Auto-advance sequence
    orderSeq++;
    localStorage.setItem('aether_pos_seq', String(orderSeq));
    updateOrderNumber();

    // Reset active cart
    activeCart = [];
    activeDiscountPct = 0;
    if (discountSelect) discountSelect.value = '0';
    renderTicket();
  };

  if (completeSaleBtn) completeSaleBtn.addEventListener('click', completeSale);

  if (closeReceipt) closeReceipt.addEventListener('click', function(){ if (modalReceipt) modalReceipt.style.display = 'none'; });
  if (newOrderBtn) newOrderBtn.addEventListener('click', function(){ if (modalReceipt) modalReceipt.style.display = 'none'; });
  if (printReceiptBtn) {
    printReceiptBtn.addEventListener('click', function() {
      window.print();
    });
  }

  // --- 9. SHIFT / X-READ SALES REPORT ---
  var reportBtn = $('#pos-btn-x-report');
  var modalReport = $('#pos-modal-report');
  var closeReport = $('#pos-close-report');
  var doneReport = $('#pos-btn-done-report');
  var clearHistoryBtn = $('#pos-btn-clear-history');

  var openReportModal = function() {
    var statSales = $('#pos-stat-sales');
    var statOrders = $('#pos-stat-orders');
    var statAvg = $('#pos-stat-avg');
    var historyContainer = $('#pos-report-history');

    var totalSales = salesHistory.reduce(function(acc, s){ return acc + s.total; }, 0);
    var count = salesHistory.length;
    var avg = count > 0 ? (totalSales / count) : 0;

    if (statSales) statSales.textContent = curr + totalSales.toFixed(2);
    if (statOrders) statOrders.textContent = count;
    if (statAvg) statAvg.textContent = curr + avg.toFixed(2);

    if (historyContainer) {
      if (!count) {
        historyContainer.innerHTML = '<div style="text-align:center; padding:20px; color:var(--pos-text-dim);">No sales recorded in this shift yet.</div>';
      } else {
        historyContainer.innerHTML = salesHistory.map(function(s) {
          return '<div class="pos-history-row">' +
            '<div>' +
              '<div style="font-weight:700; color:var(--pos-text);">' + s.orderNum + ' <span style="font-size:0.7rem; color:var(--pos-accent); font-weight:600;">(' + s.payMethod + ')</span></div>' +
              '<div style="font-size:0.7rem; color:var(--pos-text-dim);">' + s.displayDate + ' • ' + s.orderType + '</div>' +
            '</div>' +
            '<div style="font-size:0.95rem; font-weight:800; font-family:var(--pos-mono); color:var(--pos-accent);">' + curr + s.total.toFixed(2) + '</div>' +
          '</div>';
        }).join('');
      }
    }

    if (modalReport) modalReport.style.display = 'flex';
  };

  if (reportBtn) reportBtn.addEventListener('click', openReportModal);
  if (closeReport) closeReport.addEventListener('click', function(){ if (modalReport) modalReport.style.display = 'none'; });
  if (doneReport) doneReport.addEventListener('click', function(){ if (modalReport) modalReport.style.display = 'none'; });

  if (clearHistoryBtn) {
    clearHistoryBtn.addEventListener('click', function() {
      if (confirm('Reset shift sales history? This clears all recorded transactions for this session.')) {
        salesHistory = [];
        localStorage.setItem('aether_pos_sales', '[]');
        openReportModal();
      }
    });
  }

  // --- 10. CLEANUP TEARDOWN ---
  el.__wbDestroy = function() {
    clearInterval(clockTimer);
  };
}
